from itertools import *
print(*'1234567')
for per in permutations('ABCDEFG'):
    p1 = '13 14 16 24 25 36 45 57 67'
    p2 = 'AB AC BC CE AF DG DE DF EG'
    for a, b in zip('1234567', per):
        p1 = p1.replace(a, b)
        if all(c in p2 or c[::-1] in p2 for c in p1.split()):
            print(*per)

